    #[test]
    fn full_r5_terrain_native_save_uses_bulk_capacity_and_fresh_hydration_is_exact() {
        const PREVIOUS_COMMIT_PAYLOAD_BYTES: usize = 6 * 1024 * 1024;

        assert_eq!(
            INTEGRATED_RUNTIME_PERSISTENCE_MAX_COMMIT_PAYLOAD_BYTES,
            MAX_RECORD_BYTES_V1
        );
        assert_eq!(
            INTEGRATED_RUNTIME_PERSISTENCE_MAX_PACKET_BYTES,
            DEFAULT_DISPATCH_MAX_PACKET_BYTES_V1
        );
        assert_eq!(
            INTEGRATED_RUNTIME_PERSISTENCE_MAX_QUEUED_BYTES,
            DEFAULT_DISPATCH_MAX_BYTES_V1
        );

        let fixture = blockwild_generation::fixture_request("full-r5-native-save-capacity", 0, 0, 1);
        let mut config = IntegratedRuntimeConfigV2 {
            world_seed: fixture.seed_text,
            terrain_content_hash: parse_canonical_hash(&fixture.content_hash).unwrap(),
            generator_hash: parse_canonical_hash(&fixture.generator_hash).unwrap(),
            ..IntegratedRuntimeConfigV2::default()
        };
        config.block_catalog.water_block_id = GeneratedBlock::WATER;
        let mut source = IntegratedRuntimeV2::new(config.clone()).unwrap();
        let desired_chunks = (-2..=2)
            .flat_map(|chunk_x| (-2..=2).map(move |chunk_z| IntegratedTerrainChunkCoordinateV1 { chunk_x, chunk_z }))
            .collect::<Vec<_>>();
        let terrain = source
            .reconcile_terrain_residency(&IntegratedTerrainResidencyReconcileBatchV2 {
                expected_world_revision: source.world().revision(),
                generation_options_json: source.config().generation_options_json.clone(),
                desired_chunks,
            })
            .unwrap();
        assert_eq!(terrain.generated_chunk_count, 25);
        assert_eq!(terrain.resident_sections, 300);

        let mut player_record = EntityCompatibilityRecord::new("player:one", "player:one", "player");
        player_record.class = EntityClass::Player;
        player_record.position = EntityVec3::new(8.0, 63.5, 8.0);
        player_record.health = 20.0;
        player_record.maximum_health = 20.0;
        player_record.custom.insert("physics.grounded".into(), "true".into());
        let mut player_batch = IntegratedRuntimeBatchV2::empty("spawn-full-r5-save-player", source.identity());
        player_batch.entities.push(EntityCommandBatch {
            schema: ENTITY_COMMAND_SCHEMA,
            sequence: 1,
            expected_revision: 0,
            tick: 0,
            commands: vec![EntityCommand::Spawn {
                record: player_record,
                residency: EntityResidency::Hot,
            }],
        });
        assert!(source.commit(player_batch).accepted());
        source
            .bind_player(RuntimePlayerBindingWireV1 {
                external_entity_id: "player:one".into(),
                actor_id: "player:one".into(),
                player_id: PlayerId::new(1, 1),
                creative_mode: false,
                radius: 0.35,
                standing_height: 1.8,
                crouching_height: 1.35,
                mass: 80.0,
                walk_speed: 4.3,
                sprint_speed: 6.2,
                creative_flight_speed: 8.0,
                maximum_oxygen_seconds: 15.0,
            })
            .unwrap();

        let native_records = source.build_native_state_records().unwrap();
        let world_record = native_records
            .iter()
            .find(|record| {
                record.address.kind == RecordKind::ChunkEdits && record.address.record_id == NATIVE_WORLD_RECORD_ID_V1
            })
            .expect("full-residency native world record");
        assert!(
            world_record.payload.len() > PREVIOUS_COMMIT_PAYLOAD_BYTES,
            "the regression must retain the browser-proven record that exceeded the former 6 MiB lane"
        );
        assert!(world_record.payload.len() <= NATIVE_RECORD_MAX_BYTES_V1);
        let expected_world_payload = world_record.payload.clone();

        let progress = source.finalize_native_save("full-r5-native-save", 105).unwrap();
        assert!(progress.dispatcher_request_id.is_some());
        let packet = source
            .poll_persistence_platform(INTEGRATED_RUNTIME_PERSISTENCE_MAX_PACKET_BYTES)
            .unwrap()
            .expect("full-residency authority commit platform packet");
        assert!(packet.bytes.len() > PREVIOUS_COMMIT_PAYLOAD_BYTES);
        assert!(packet.bytes.len() <= INTEGRATED_RUNTIME_PERSISTENCE_MAX_PACKET_BYTES);
        let request = blockwild_persistence::decode_persistence_browser_request_v1(&packet.bytes).unwrap();
        let blockwild_persistence::PersistenceBrowserRequestV1::Commit {
            request_id,
            transaction,
            checkpoint,
        } = request
        else {
            panic!("expected full-residency authority commit request")
        };
        let committed_world_payload = transaction
            .mutations
            .iter()
            .find_map(|mutation| match mutation {
                blockwild_persistence::Mutation::Put { address, payload, .. }
                    if address.kind == RecordKind::ChunkEdits && address.record_id == NATIVE_WORLD_RECORD_ID_V1 =>
                {
                    Some(payload)
                }
                _ => None,
            })
            .expect("full native world envelope fits the prepared transaction");
        assert_eq!(committed_world_payload, &expected_world_payload);
        let response = blockwild_persistence::encode_persistence_browser_response_v1(
            &blockwild_persistence::PersistenceBrowserResponseV1::Commit(
                blockwild_persistence::PersistenceBrowserCommitResultV1 {
                    request_id,
                    code: blockwild_persistence::PersistenceBrowserCommitCodeV1::Committed,
                    transaction_id: transaction.transaction_id.clone(),
                    journal_sequence: transaction.next_journal_sequence,
                    durable_hash: CanonicalHash([0x78; 16]),
                    checkpoint_hash: checkpoint.checkpoint_hash,
                    verified_readback: true,
                    message: "durable full-r5 fixture".into(),
                },
            ),
        )
        .unwrap();
        let outcome = source
            .complete_persistence_platform(packet.transfer_token, &response)
            .unwrap();
        assert_eq!(outcome.status, PersistenceDispatchStatusV1::Accepted);
        let mut commit_count = 1_u32;
        for _ in 0..64 {
            let diagnostics = source.persistence_authority().diagnostics();
            if diagnostics.dirty_records == 0
                && !diagnostics.commit_in_flight
                && source.prepared_persistence_commits.is_empty()
                && source.persistence_dispatcher().is_idle()
            {
                break;
            }
            accept_next_authority_commit(&mut source);
            commit_count = commit_count.saturating_add(1);
        }
        assert_eq!(
            commit_count, 1,
            "the 25-chunk native save should fit one bounded prefix commit"
        );
        assert_eq!(source.persistence_authority().diagnostics().dirty_records, 0);
        assert!(!source.persistence_authority().diagnostics().commit_in_flight);
        assert!(source.prepared_persistence_commits.is_empty());
        assert!(source.persistence_dispatcher().is_idle());

        let expected_world_hash = source.world().canonical_state_hash();
        let expected_world_revision = source.world().revision();
        let expected_chunks = source.world().resident_chunk_coordinates();
        let expected_entities_hash = source.entities().canonical_hash();
        let expected_gameplay_hash = source.gameplay().state.state_hash();
        let expected_player = source.player().cloned();
        let expected_replay = source.replay_hash();
        let recovered = recovered_authority_save(&source);
        let mut restored = IntegratedRuntimeV2::new(config).unwrap();
        restored
            .recovered_save_sets
            .insert("full-r5-native-save".into(), recovered);
        let summary = restored.hydrate_recovery("full-r5-native-save").unwrap();
        assert_eq!(summary.native_domains, INTEGRATED_RUNTIME_NATIVE_DOMAIN_COUNT_V1);
        assert_eq!(restored.world().canonical_state_hash(), expected_world_hash);
        assert_eq!(restored.world().revision(), expected_world_revision);
        assert_eq!(restored.world().resident_chunk_coordinates(), expected_chunks);
        assert_eq!(restored.entities().canonical_hash(), expected_entities_hash);
        assert_eq!(restored.gameplay().state.state_hash(), expected_gameplay_hash);
        assert_eq!(restored.player(), expected_player.as_ref());
        assert_eq!(restored.replay_hash(), expected_replay);
    }

    #[test]
    fn durable_native_hydration_rebinds_only_session_and_preserves_authority_proofs() {
        let source_config = IntegratedRuntimeConfigV2 {
            world_seed: "durable-session-rebind-world".into(),
            session_id: "durable-session-a".into(),
            ..IntegratedRuntimeConfigV2::default()
        };
        let mut source = runtime_with_bound_player_config(source_config.clone());
        source.native_world_extension_bytes = vec![0x80, 1, 0xff];
        source.native_runtime_extension_bytes = vec![0xff, 2, 0x80];
        source.native_gameplay_extension_bytes = vec![3, 0x80, 0xff];
        source.native_world_view_extension_bytes = vec![0, 4, 0xff];
        let edit_position = CellPositionV1 { x: 2, y: 1, z: 2 };
        let mut edit = IntegratedRuntimeBatchV2::empty("durable-rebind-edit", source.identity());
        edit.world.push(WorldMutationBatchR4V1 {
            schema_version: blockwild_authority::WORLD_AUTHORITY_SCHEMA_V1,
            batch_id: "durable-rebind-edit".into(),
            authority_id: "fixture".into(),
            address: source.world().active_address().clone(),
            expected_revision: source.world().revision(),
            commands: vec![blockwild_authority::WorldMutationCommandR4V1::SetBlock {
                position: edit_position,
                block_id: 1,
                facing: None,
            }],
        });
        assert!(source.commit(edit).accepted());
        source.finalize_native_save("session-a-save", 101).unwrap();
        accept_all_authority_commits(&mut source);
        let recovered = recovered_authority_save(&source);

        let expected_world = source.world().canonical_state_hash();
        let expected_entities = source.entities().canonical_hash();
        let expected_gameplay = source.gameplay().state.state_hash();
        let expected_world_view = source.world_view().state.state_hash();
        let expected_journal = source.persistence().state_hash();
        let expected_authority = source.persistence_authority().state_hash();
        let expected_player = source.player().cloned();
        let expected_replay = source.replay_hash();

        let mut target_config = source_config;
        target_config.session_id = "durable-session-b".into();
        let mut target = IntegratedRuntimeV2::new(target_config).unwrap();
        target.recovered_save_sets.insert("session-rebind".into(), recovered);
        target.hydrate_recovery("session-rebind").unwrap();

        assert_eq!(target.config.session_id, "durable-session-b");
        assert_eq!(target.world().canonical_state_hash(), expected_world);
        assert_eq!(target.entities().canonical_hash(), expected_entities);
        assert_eq!(target.gameplay().state.state_hash(), expected_gameplay);
        assert_eq!(target.world_view().state.state_hash(), expected_world_view);
        assert_eq!(target.persistence().state_hash(), expected_journal);
        assert_eq!(target.persistence_authority().state_hash(), expected_authority);
        assert_eq!(target.player(), expected_player.as_ref());
        assert_eq!(target.replay_hash(), expected_replay);
        assert_eq!(target.native_world_extension_bytes, vec![0x80, 1, 0xff]);
        assert_eq!(target.native_runtime_extension_bytes, vec![0xff, 2, 0x80]);
        assert_eq!(target.native_gameplay_extension_bytes, vec![3, 0x80, 0xff]);
        assert_eq!(target.native_world_view_extension_bytes, vec![0, 4, 0xff]);
        assert!(target.durable_network_state_pristine);
        assert_eq!(target.replication.record_count(), 0);
        assert!(target.replication_record_hashes.is_empty());
        assert_eq!(
            target.network.authority_fingerprint(),
            NetworkBrowserAuthorityRuntimeV1::new("durable-session-b".into())
                .unwrap()
                .authority_fingerprint(),
        );

        let expected_control_identity = source.identity();
        let control = source.export_runtime_checkpoint().unwrap();
        let control_restored =
            IntegratedRuntimeV2::restore_runtime_checkpoint(&control, integrated_runtime_checkpoint_hash_v1(&control))
                .unwrap();
        assert_eq!(control_restored.config.session_id, "durable-session-a");
        assert_eq!(control_restored.identity(), expected_control_identity);
    }

    #[test]
    fn durable_session_rebind_rejects_every_immutable_config_mismatch_atomically() {
        let source_config = IntegratedRuntimeConfigV2 {
            world_seed: "durable-mismatch-source".into(),
            session_id: "durable-mismatch-a".into(),
            content_hash: CanonicalHash([0x11; 16]),
            generator_hash: CanonicalHash([0x22; 16]),
            ..IntegratedRuntimeConfigV2::default()
        };
        let mut source = runtime_with_section_config(source_config.clone());
        source.finalize_native_save("mismatch-source", 102).unwrap();
        accept_all_authority_commits(&mut source);
        let recovered = recovered_authority_save(&source);

        let mut base = source_config;
        base.session_id = "durable-mismatch-b".into();
        let mut cases = Vec::new();
        let mut seed = base.clone();
        seed.world_seed = "different-seed".into();
        cases.push(("seed", seed, "recovery-config"));
        let mut terrain = base.clone();
        terrain.terrain_content_hash = CanonicalHash([0x33; 16]);
        cases.push(("terrain", terrain, "recovery-config"));
        let mut options = base.clone();
        options.generation_options_json = options
            .generation_options_json
            .replace("\"biomeScale\":1.35", "\"biomeScale\":1.25");
        cases.push(("options", options, "recovery-config"));
        let mut catalog = base.clone();
        catalog.block_catalog.water_block_id = catalog.block_catalog.water_block_id.saturating_add(1);
        cases.push(("catalog", catalog, "recovery-config"));
        let mut content = base.clone();
        content.content_hash = CanonicalHash([0x44; 16]);
        cases.push(("content", content, "recovery-fingerprint"));
        let mut generator = base.clone();
        generator.generator_hash = CanonicalHash([0x55; 16]);
        cases.push(("generator", generator, "recovery-fingerprint"));
        let mut address = base;
        address.location_id = "different-location".into();
        cases.push(("address", address, "recovery-fingerprint"));

        for (label, config, expected_code) in cases {
            let mut target = IntegratedRuntimeV2::new(config).unwrap();
            target.recovered_save_sets.insert(label.into(), recovered.clone());
            let before = target.identity();
            assert_eq!(
                target.hydrate_recovery(label).unwrap_err().code,
                expected_code,
                "{label}"
            );
            assert_eq!(target.identity(), before, "{label}");
            assert!(target.recovered_save_sets.contains_key(label), "{label}");
        }
    }

    #[test]
    fn legacy_durable_core_requires_exact_session_and_v5_proofs_are_all_or_nothing() {
        let source_config = IntegratedRuntimeConfigV2 {
            world_seed: "legacy-durable-session".into(),
            session_id: "legacy-durable-session-a".into(),
            ..IntegratedRuntimeConfigV2::default()
        };
        let mut source = runtime_with_section_config(source_config.clone());
        source.finalize_native_save("legacy-session", 104).unwrap();
        accept_all_authority_commits(&mut source);
        let mut legacy = recovered_authority_save(&source);
        rewrite_recovery_runtime_core(&mut legacy, |core| {
            core.schema = NATIVE_RUNTIME_CORE_SCHEMA_V4;
            core.durable_network_drained_proof = None;
            core.durable_state_proof = None;
            core.durable_replay_proof = None;
        });

        let mut same_session = IntegratedRuntimeV2::new(source_config.clone()).unwrap();
        same_session
            .recovered_save_sets
            .insert("legacy-same".into(), legacy.clone());
        same_session.hydrate_recovery("legacy-same").unwrap();
        assert_eq!(
            same_session.world().canonical_state_hash(),
            source.world().canonical_state_hash()
        );

        let mut other_config = source_config;
        other_config.session_id = "legacy-durable-session-b".into();
        let mut different_session = IntegratedRuntimeV2::new(other_config).unwrap();
        different_session
            .recovered_save_sets
            .insert("legacy-different".into(), legacy);
        let before = different_session.identity();
        assert_eq!(
            different_session.hydrate_recovery("legacy-different").unwrap_err().code,
            "recovery-config"
        );
        assert_eq!(different_session.identity(), before);

        let mut partial = recovered_authority_save(&source);
        rewrite_recovery_runtime_core(&mut partial, |core| {
            core.durable_network_drained_proof = None;
        });
        let mut partial_target = IntegratedRuntimeV2::new(IntegratedRuntimeConfigV2 {
            world_seed: "legacy-durable-session".into(),
            session_id: "legacy-durable-session-c".into(),
            ..IntegratedRuntimeConfigV2::default()
        })
        .unwrap();
        partial_target.recovered_save_sets.insert("partial-v5".into(), partial);
        let before = partial_target.identity();
        assert_eq!(
            partial_target.hydrate_recovery("partial-v5").unwrap_err().code,
            "recovery-proof-incomplete"
        );
        assert_eq!(partial_target.identity(), before);
        assert!(partial_target.recovered_save_sets.contains_key("partial-v5"));
    }

    #[test]
    fn active_network_authority_cannot_emit_or_rebind_a_durable_native_save() {
        let source_config = IntegratedRuntimeConfigV2 {
            world_seed: "network-active-durable-source".into(),
            session_id: "network-active-session-a".into(),
            ..IntegratedRuntimeConfigV2::default()
        };
        let mut source = runtime_with_section_config(source_config.clone());
        activate_fixture_network_grant(&mut source);
        let before_save = source.identity();
        assert_eq!(
            source.finalize_native_save("network-active", 103).unwrap_err().code,
            "native-save-network-active"
        );
        assert_eq!(source.identity(), before_save);

        // A control-style bundle deliberately has no durable drain proof when
        // network authority has been exercised. Even if wrapped in a valid
        // persistence checkpoint, durable hydration must reject it atomically.
        let unproven = force_unattested_native_recovery(&mut source);
        let mut target_config = source_config;
        target_config.session_id = "network-active-session-b".into();
        let mut target = IntegratedRuntimeV2::new(target_config).unwrap();
        target.recovered_save_sets.insert("unproven-network".into(), unproven);
        let before_hydrate = target.identity();
        assert_eq!(
            target.hydrate_recovery("unproven-network").unwrap_err().code,
            "recovery-proof-incomplete"
        );
        assert_eq!(target.identity(), before_hydrate);
        assert!(target.recovered_save_sets.contains_key("unproven-network"));
    }

    #[test]
    fn recovery_hydration_is_atomic_and_compatibility_bytes_are_export_only() {
        let mut source = runtime_with_section();
        let position = CellPositionV1 { x: 1, y: 1, z: 1 };
        let expected = source.world().identity();
        let mut batch = IntegratedRuntimeBatchV2::empty("saved-world-edit", source.identity());
        batch.world.push(WorldMutationBatchR4V1 {
            schema_version: blockwild_authority::WORLD_AUTHORITY_SCHEMA_V1,
            batch_id: "saved-world-edit".into(),
            authority_id: "fixture".into(),
            address: expected.address,
            expected_revision: expected.revision,
            commands: vec![blockwild_authority::WorldMutationCommandR4V1::SetBlock {
                position,
                block_id: 1,
                facing: None,
            }],
        });
        assert!(source.commit(batch).accepted());
        let compatibility = "compatibility-shell-🌿".as_bytes();
        source
            .stage_compatibility_save_chunk("source", 0, 1, compatibility.len() as u64, compatibility)
            .unwrap();
        source.finalize_compatibility_save("source", 12).unwrap();
        accept_next_authority_commit(&mut source);
        let recovered = recovered_authority_save(&source);

        let recovered_legacy = recovered
            .payloads
            .iter()
            .filter(|(address, _)| {
                address.kind == RecordKind::SettingsReference
                    && address.record_id.starts_with(COMPATIBILITY_RECORD_PREFIX_V1)
            })
            .map(|(_, payload)| payload.as_slice())
            .collect::<Vec<_>>()
            .concat();
        assert_eq!(recovered_legacy, compatibility, "legacy source bytes remain exact");

        let mut target = runtime_with_section();
        assert_eq!(loaded_block_id(&target, position), 0);
        let mut mismatched = recovered.clone();
        mismatched.checkpoint.content_hash = CanonicalHash([0x44; 16]);
        target.recovered_save_sets.insert("mismatch".into(), mismatched);
        let before_mismatch = target.identity();
        assert_eq!(
            target.hydrate_recovery("mismatch").unwrap_err().code,
            "recovery-fingerprint"
        );
        assert_eq!(target.identity(), before_mismatch);
        assert_eq!(loaded_block_id(&target, position), 0);

        let mut wrong_content = recovered.clone();
        let content_address = wrong_content
            .payloads
            .keys()
            .find(|address| {
                address.kind == RecordKind::SettingsReference && address.record_id == NATIVE_CONTENT_RECORD_ID_V1
            })
            .cloned()
            .expect("content native record");
        let mut wrong_content_envelope = decode_native_record_envelope_v1(
            wrong_content
                .payloads
                .get(&content_address)
                .expect("content native record"),
        )
        .unwrap();
        wrong_content_envelope.content_hash = CanonicalHash([0x55; 16]);
        wrong_content.payloads.insert(
            content_address,
            encode_native_record_envelope_v1(&wrong_content_envelope).unwrap(),
        );
        target
            .recovered_save_sets
            .insert("wrong-content-native".into(), wrong_content);
        assert_eq!(
            target.hydrate_recovery("wrong-content-native").unwrap_err().code,
            "recovery-native-identity"
        );
        assert_eq!(target.identity(), before_mismatch);

        let mut missing = recovered.clone();
        let missing_address = missing
            .payloads
            .keys()
            .find(|address| address.kind == RecordKind::Entity && address.record_id == NATIVE_ENTITY_RECORD_ID_V2)
            .cloned()
            .expect("entity native record");
        missing.payloads.remove(&missing_address);
        target.recovered_save_sets.insert("missing-native".into(), missing);
        assert_eq!(
            target.hydrate_recovery("missing-native").unwrap_err().code,
            "recovery-native-missing"
        );
        assert_eq!(target.identity(), before_mismatch);

        let mut duplicate = recovered.clone();
        let duplicate_payload = duplicate
            .payloads
            .get(&missing_address)
            .expect("entity native record")
            .clone();
        let duplicate_address = RecordAddress::new(
            target.config.universe_id.clone(),
            target.config.location_id.clone(),
            RecordKind::SettingsReference,
            "duplicate-native-envelope",
        )
        .unwrap();
        duplicate.payloads.insert(duplicate_address, duplicate_payload);
        target.recovered_save_sets.insert("duplicate-native".into(), duplicate);
        assert_eq!(
            target.hydrate_recovery("duplicate-native").unwrap_err().code,
            "recovery-native-duplicate"
        );
        assert_eq!(target.identity(), before_mismatch);

        target.recovered_save_sets.insert("ready".into(), recovered);
        let summary = target.hydrate_recovery("ready").unwrap();
        assert_eq!(summary.native_domains, INTEGRATED_RUNTIME_NATIVE_DOMAIN_COUNT_V1);
        assert_eq!(
            target.world().edit_journal().get(&position).map(|cell| cell.block_id),
            Some(1)
        );
        let chunk = target.read_hydrated_compatibility_chunk("ready", 0).unwrap();
        assert_eq!(chunk.bytes, compatibility);
        assert_eq!(chunk.chunk_count, 1);
        assert_eq!(
            target.read_hydrated_compatibility_chunk("missing", 0).unwrap_err().code,
            "hydration-export",
        );
    }

    #[test]
    fn native_save_initializes_without_a_legacy_source_and_preserves_one_later() {
        let mut native = runtime_with_section();
        let expected_world = native.world().canonical_state_hash();
        let progress = native.finalize_native_save("new-world", 88).unwrap();
        assert_eq!(progress.chunk_count, 0);
        assert_eq!(progress.received_bytes, 0);
        accept_all_authority_commits(&mut native);
        let recovered = recovered_authority_save(&native);
        let manifest_payload = recovered
            .payloads
            .iter()
            .find(|(address, _)| {
                address.kind == RecordKind::LocationManifest && address.record_id == WORLD_SAVE_MANIFEST_RECORD_ID_V1
            })
            .map(|(_, payload)| payload)
            .expect("native save manifest");
        let manifest = decode_world_save_manifest_v1(manifest_payload).unwrap();
        assert_eq!(manifest.compatibility_chunks, 0);
        assert_eq!(manifest.compatibility_byte_length, 0);

        let mut restored = runtime_with_section();
        restored.recovered_save_sets.insert("native".into(), recovered);
        let summary = restored.hydrate_recovery("native").unwrap();
        assert_eq!(summary.chunk_count, 0);
        assert_eq!(restored.world().canonical_state_hash(), expected_world);
        restored.finalize_native_save("second-native-save", 89).unwrap();

        let mut legacy_owned = runtime_with_section();
        legacy_owned
            .stage_compatibility_save_chunk("legacy", 0, 1, 3, b"old")
            .unwrap();
        legacy_owned.finalize_compatibility_save("legacy", 90).unwrap();
        accept_all_authority_commits(&mut legacy_owned);
        legacy_owned.finalize_native_save("must-not-drop-source", 91).unwrap();
        accept_all_authority_commits(&mut legacy_owned);
        let preserved = recovered_authority_save(&legacy_owned)
            .payloads
            .iter()
            .filter(|(address, _)| {
                address.kind == RecordKind::SettingsReference
                    && address.record_id.starts_with(COMPATIBILITY_RECORD_PREFIX_V1)
            })
            .map(|(_, payload)| payload.as_slice())
            .collect::<Vec<_>>()
            .concat();
        assert_eq!(preserved, b"old");
    }

    fn historical_external_test_config_v2(session_id: &str) -> IntegratedRuntimeConfigV2 {
        IntegratedRuntimeConfigV2 {
            universe_id: "world:historical-fixture".into(),
            location_id: "surface".into(),
            world_seed: "historical-seed".into(),
            session_id: session_id.into(),
            ..IntegratedRuntimeConfigV2::default()
        }
    }

    fn initial_historical_external_proposal_v2(
        config: &IntegratedRuntimeConfigV2,
        document: &[u8],
        projection_bytes: &[u8],
    ) -> HistoricalExternalDescriptorProposalV2 {
        let projection = decode_compatibility_save_binary_v1(projection_bytes).unwrap();
        let raw_sha256 = [0x11; 32];
        let raw_hex = raw_sha256.iter().map(|byte| format!("{byte:02x}")).collect::<String>();
        let document_identity = blockwild_persistence::HistoricalDocumentIdentityV2 {
            hash: persistence_payload_hash_v1(document),
            sha256: sha256_bytes_v1(document),
            byte_length: document.len() as u64,
        };
        HistoricalExternalDescriptorProposalV2 {
            schema_version: blockwild_persistence::HISTORICAL_EXTERNAL_DESCRIPTOR_SCHEMA_V2,
            immutable: blockwild_persistence::HistoricalExternalImmutableV2 {
                authority: blockwild_persistence::HistoricalExternalAuthorityV2 {
                    claim: HISTORICAL_EXTERNAL_AUTHORITY_CLAIM_V2.into(),
                    native_player: "off".into(),
                    native_rich_state: "not-adopted".into(),
                },
                profile: HISTORICAL_EXTERNAL_PROFILE_V2.into(),
                native_execution_scope: HISTORICAL_EXTERNAL_NATIVE_EXECUTION_SCOPE_V2.into(),
                source: blockwild_persistence::HistoricalExternalImportSourceV2 {
                    schema_version: 1,
                    provenance: "uploaded-file-bytes".into(),
                    source_format: "blockwild-world-export-v1".into(),
                    encoding: "utf-8".into(),
                    archive_world_id: "blockwild-original-import-sources-v1".into(),
                    object_id: format!("sha256-{raw_hex}"),
                    raw_sha256,
                    byte_length: 17,
                    generator_version: 17,
                },
                initial_document: document_identity.clone(),
                plan_hash: CanonicalHash([0x21; 16]),
                custody_root: CanonicalHash([0x22; 16]),
                external_state_flags: LEGACY_STATE_PLAYER_V1 | LEGACY_STATE_GAMEPLAY_V1,
                target: blockwild_persistence::HistoricalExternalTargetV2 {
                    catalog_world_id: "historical-fixture".into(),
                    universe_id: config.universe_id.clone(),
                    location_id: config.location_id.clone(),
                    world_seed: config.world_seed.clone(),
                    content_hash: config.content_hash,
                    generation_identity: blockwild_persistence::HistoricalExternalGenerationIdentityV2 {
                        schema_version: 1,
                        generator_hash: config.generator_hash,
                        terrain_content_hash: config.terrain_content_hash,
                        generation_options_json: config.generation_options_json.clone(),
                        generation_options_hash: persistence_payload_hash_v1(config.generation_options_json.as_bytes()),
                        generation_options_byte_length: config.generation_options_json.len() as u64,
                    },
                    options_semantic_hash: CanonicalHash([0x23; 16]),
                    options_byte_length: 1,
                },
                bwas: blockwild_persistence::HistoricalExternalBwasV2 {
                    projection_hash: persistence_payload_hash_v1(projection_bytes),
                    projection_byte_length: projection_bytes.len() as u64,
                    compatibility_checksum: parse_canonical_hash(&projection.compatibility_checksum).unwrap(),
                    extension_checksum: parse_canonical_hash(&projection.extension_checksum).unwrap(),
                    edit_count: projection.edits.iter().map(|chunk| chunk.entries.len() as u64).sum(),
                    facing_count: projection.facings.len() as u64,
                },
            },
            external: blockwild_persistence::HistoricalExternalFieldsV2 {
                current_document: blockwild_persistence::HistoricalDocumentRevisionIdentityV2 {
                    identity: document_identity,
                    revision: 1,
                },
                expected_previous_document: None,
                chunks: vec![blockwild_persistence::HistoricalExternalDocumentChunkFingerprintV2 {
                    index: 0,
                    byte_offset: 0,
                    byte_length: document.len() as u32,
                    payload_hash: persistence_payload_hash_v1(document),
                }],
                chunk_set_hash: CanonicalHash::default(),
            },
            proposal_hash: CanonicalHash::default(),
        }
        .with_calculated_hash()
        .unwrap()
    }

    struct HistoricalSuccessorResumeFixtureV2 {
        config: IntegratedRuntimeConfigV2,
        document: Vec<u8>,
        proposal_bytes: Vec<u8>,
        recovery: PagedRecoveryCompleteV1,
        prior_recovery: PagedRecoveryCompleteV1,
        prior_checkpoint: Checkpoint,
        prior_checkpoint_bytes: Vec<u8>,
    }

    fn historical_successor_resume_fixture_v2() -> HistoricalSuccessorResumeFixtureV2 {
        let config = historical_external_test_config_v2("historical-successor-source");
        let projection_source = IntegratedRuntimeV2::new(config.clone()).unwrap();
        let projection =
            encode_compatibility_save_binary_v1(&projection_source.world().export_compatibility_save()).unwrap();
        let document_v1 = br#"{"schema":2,"save":{"player":{"x":1},"opaque":"prior"}}"#;
        let proposal_v1 = initial_historical_external_proposal_v2(&config, document_v1, &projection);
        let proposal_v1_bytes =
            blockwild_persistence::encode_historical_external_descriptor_proposal_v2(&proposal_v1).unwrap();

        let mut source = IntegratedRuntimeV2::new(config.clone()).unwrap();
        source
            .stage_compatibility_save_chunk("historical-successor-v1", 0, 1, document_v1.len() as u64, document_v1)
            .unwrap();
        source
            .migrate_historical_external_v2("historical-successor-v1", 401, &proposal_v1_bytes, &projection)
            .unwrap();
        accept_all_authority_commits(&mut source);
        let prior = recovered_authority_save(&source);
        let prior_descriptor = source
            .historical_external_descriptor_from_authority_v2()
            .unwrap()
            .expect("durable prior BWHE");

        let document_v2 = br#"{"schema":2,"save":{"player":{"x":2},"opaque":"successor"}}"#.to_vec();
        let document_identity_v2 = blockwild_persistence::HistoricalDocumentIdentityV2 {
            hash: persistence_payload_hash_v1(&document_v2),
            sha256: sha256_bytes_v1(&document_v2),
            byte_length: document_v2.len() as u64,
        };
        let proposal_v2 = HistoricalExternalDescriptorProposalV2 {
            schema_version: prior_descriptor.schema_version,
            immutable: prior_descriptor.immutable.clone(),
            external: blockwild_persistence::HistoricalExternalFieldsV2 {
                current_document: blockwild_persistence::HistoricalDocumentRevisionIdentityV2 {
                    identity: document_identity_v2,
                    revision: prior_descriptor.mutable.external.current_document.revision + 1,
                },
                expected_previous_document: Some(prior_descriptor.mutable.external.current_document.clone()),
                chunks: vec![blockwild_persistence::HistoricalExternalDocumentChunkFingerprintV2 {
                    index: 0,
                    byte_offset: 0,
                    byte_length: document_v2.len() as u32,
                    payload_hash: persistence_payload_hash_v1(&document_v2),
                }],
                chunk_set_hash: CanonicalHash::default(),
            },
            proposal_hash: CanonicalHash::default(),
        }
        .with_calculated_hash()
        .unwrap();
        let proposal_bytes =
            blockwild_persistence::encode_historical_external_descriptor_proposal_v2(&proposal_v2).unwrap();
        source
            .stage_compatibility_save_chunk("historical-successor-v2", 0, 1, document_v2.len() as u64, &document_v2)
            .unwrap();
        source
            .finalize_historical_external_save_v2(
                "historical-successor-v2",
                402,
                &proposal_bytes,
                &encode_checkpoint(&prior.checkpoint),
            )
            .unwrap();
        accept_all_authority_commits(&mut source);
        let target = recovered_authority_save(&source);
        assert_eq!(
            target.checkpoint.journal_sequence,
            prior.checkpoint.journal_sequence + 1,
            "fixture successor must be one direct canonical child"
        );
        assert_eq!(
            target.checkpoint.parent_checkpoint_id.as_deref(),
            Some(prior.checkpoint.checkpoint_id.as_str())
        );
        let descriptor_address =
            historical_external_descriptor_address_v2(&config.universe_id, &config.location_id).unwrap();
        let target_descriptor = target
            .checkpoint
            .records
            .iter()
            .find(|record| record.address == descriptor_address)
            .expect("successor target BWHE")
            .clone();
        let mut prefix_records = prior.checkpoint.records.clone();
        let descriptor_index = prefix_records
            .binary_search_by(|record| record.address.cmp(&descriptor_address))
            .expect("prior BWHE address");
        prefix_records[descriptor_index] = target_descriptor;
        let prefix_payloads = prefix_records
            .iter()
            .map(|record| {
                let source = if record.address == descriptor_address {
                    &target.payloads
                } else {
                    &prior.payloads
                };
                (
                    record.address.clone(),
                    source.get(&record.address).expect("exact prefix payload").clone(),
                )
            })
            .collect::<BTreeMap<_, _>>();
        let prefix_checkpoint = Checkpoint::new(
            format!("bwcp:{}:successor-prefix", target.checkpoint.journal_sequence),
            Some(prior.checkpoint.checkpoint_id.clone()),
            target.checkpoint.world_id.clone(),
            target.checkpoint.journal_sequence,
            target.checkpoint.generator_hash,
            target.checkpoint.content_hash,
            target.checkpoint.created_at,
            prefix_records,
        )
        .unwrap();

        HistoricalSuccessorResumeFixtureV2 {
            config,
            document: document_v2,
            proposal_bytes,
            recovery: PagedRecoveryCompleteV1 {
                checkpoint: prefix_checkpoint,
                payloads: prefix_payloads,
                missing_record_keys: Vec::new(),
            },
            prior_recovery: prior.clone(),
            prior_checkpoint_bytes: encode_checkpoint(&prior.checkpoint),
            prior_checkpoint: prior.checkpoint,
        }
    }

    fn historical_successor_resume_runtime_v2(
        fixture: &HistoricalSuccessorResumeFixtureV2,
        recovery: PagedRecoveryCompleteV1,
    ) -> IntegratedRuntimeV2 {
        let mut config = fixture.config.clone();
        config.session_id = "historical-successor-resume".into();
        let mut runtime = IntegratedRuntimeV2::new(config.clone()).unwrap();
        runtime
            .recovered_save_sets
            .insert("durable-prior".into(), fixture.prior_recovery.clone());
        runtime
            .hydrate_historical_external_recovery_v2("durable-prior")
            .unwrap();
        runtime
            .stage_compatibility_save_chunk(
                "historical-successor-v2",
                0,
                1,
                fixture.document.len() as u64,
                &fixture.document,
            )
            .unwrap();
        runtime.recovered_save_sets.insert("successor-prefix".into(), recovery);
        runtime
    }

    fn assert_historical_successor_resume_rejected_without_mutation_v2(
        runtime: &mut IntegratedRuntimeV2,
        proposal_bytes: &[u8],
        prior_checkpoint_bytes: &[u8],
        expected_recovery: &PagedRecoveryCompleteV1,
    ) {
        let before = runtime.identity();
        let error = runtime
            .finalize_historical_external_save_v2(
                "historical-successor-v2",
                402,
                proposal_bytes,
                prior_checkpoint_bytes,
            )
            .unwrap_err();
        assert_eq!(error.code, "historical-external-resume");
        assert_eq!(runtime.identity(), before);
        assert_eq!(
            runtime.recovered_save_sets.get("successor-prefix"),
            Some(expected_recovery)
        );
        assert!(runtime.save_stages.contains_key("historical-successor-v2"));
        assert!(runtime.persistence_authority().checkpoint().is_some());
        assert!(!runtime.persistence_authority().records().is_empty());
        assert!(runtime.persistence_dispatcher().is_idle());
        assert!(runtime.prepared_persistence_commits.is_empty());
    }

    #[test]
    fn historical_successor_resume_rejects_unknown_record_atomically() {
        let fixture = historical_successor_resume_fixture_v2();
        let mut recovery = fixture.recovery.clone();
        let address = RecordAddress::new(
            &fixture.config.universe_id,
            &fixture.config.location_id,
            RecordKind::SettingsReference,
            "foreign-successor-record",
        )
        .unwrap();
        let payload = b"validly-hashed-but-unknown".to_vec();
        let descriptor = RecordDescriptor {
            address: address.clone(),
            revision: 1,
            byte_length: payload.len() as u32,
            payload_hash: persistence_payload_hash_v1(&payload),
        };
        let mut records = recovery.checkpoint.records.clone();
        records.push(descriptor);
        records.sort_by(|left, right| left.address.cmp(&right.address));
        recovery.payloads.insert(address, payload);
        recovery.checkpoint = Checkpoint::new(
            recovery.checkpoint.checkpoint_id.clone(),
            recovery.checkpoint.parent_checkpoint_id.clone(),
            recovery.checkpoint.world_id.clone(),
            recovery.checkpoint.journal_sequence,
            recovery.checkpoint.generator_hash,
            recovery.checkpoint.content_hash,
            recovery.checkpoint.created_at,
            records,
        )
        .unwrap();
        let mut runtime = historical_successor_resume_runtime_v2(&fixture, recovery.clone());
        assert_historical_successor_resume_rejected_without_mutation_v2(
            &mut runtime,
            &fixture.proposal_bytes,
            &fixture.prior_checkpoint_bytes,
            &recovery,
        );
    }

